package org.xingmu.tv;
import android.graphics.*;import android.widget.ImageView;import java.io.*;import java.net.*;import java.util.concurrent.*;
/** Bounded original-source poster downloads. Failed images retain the artwork placeholder. */
final class PosterImage {
 private static final android.util.LruCache<String,Bitmap> cache=new android.util.LruCache<String,Bitmap>(8*1024*1024){protected int sizeOf(String k,Bitmap v){return v.getByteCount();}};
 private static final ThreadPoolExecutor worker=new ThreadPoolExecutor(2,2,30,TimeUnit.SECONDS,new ArrayBlockingQueue<>(24));
 static void load(ImageView view,String address){view.setTag(address);if(!CatalogParser.safeMediaUrl(address))return;Bitmap saved=cache.get(address);if(saved!=null){view.setImageBitmap(saved);return;}try{worker.execute(()->{try{Bitmap bitmap=fetch(address);if(bitmap==null)return;cache.put(address,bitmap);view.post(()->{if(address.equals(view.getTag()))view.setImageBitmap(bitmap);});}catch(IOException|RuntimeException ignored){}});}catch(RejectedExecutionException ignored){}}
 private static Bitmap fetch(String address)throws IOException{for(int hop=0;hop<4;hop++){if(!CatalogParser.safeMediaUrl(address))return null;HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();c.setConnectTimeout(4000);c.setReadTimeout(4000);c.setInstanceFollowRedirects(false);try{int status=c.getResponseCode();if(status>=300&&status<400){String location=c.getHeaderField("Location");if(location==null)return null;address=new URL(new URL(address),location).toString();continue;}if(status!=200)return null;ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] block=new byte[4096];int size;while((size=in.read(block))!=-1){if(out.size()+size>2_000_000)return null;out.write(block,0,size);}}byte[] bytes=out.toByteArray();BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(options.outWidth<=0||options.outHeight<=0)return null;options.inSampleSize=1;while(options.outWidth/options.inSampleSize>640||options.outHeight/options.inSampleSize>960)options.inSampleSize*=2;options.inJustDecodeBounds=false;return BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);}finally{c.disconnect();}}return null;}
}
